-- Function: public.fn_get_teacher_attendance_summary
-- Backup generated on 2026-10-25 20:33:42

CREATE OR REPLACE FUNCTION public.fn_get_teacher_attendance_summary(p_tenant_id uuid, p_branch_id uuid, p_date date)  RETURNS TABLE(teacher_id uuid, status character varying, clock_in_time time without time zone, clock_out_time time without time zone, teacher_name character varying, classroom_id uuid)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT ta.teacher_id, ta.status::VARCHAR, ta.clock_in_time, ta.clock_out_time,            (t.first_name || ' ' || t.last_name)::VARCHAR AS teacher_name,            ct.classroom_id     FROM teacher_attendance ta     JOIN teachers t ON ta.teacher_id = t.id     LEFT JOIN classroom_teachers ct ON t.user_id = ct.user_id     WHERE ta.tenant_id = p_tenant_id AND ta.branch_id = p_branch_id AND ta.attendance_date = p_date       AND (ta.status = 'Present' OR ta.status = 'Late')       AND ta.clock_out_time IS NULL; END; $function$ ;
